import { useRef } from 'react'
import { useFrame } from '@react-three/fiber'

/**
 * <Gear teeth={n} radius={r} spinSpeed={s} />
 *
 * Renders a group containing:
 *  - a cylindrical hub along the Z axis
 *  - n box teeth evenly spaced around the circumference at distance `radius`
 *
 * The whole gear spins about Z at `spinSpeed` radians per second.
 */
export function Gear({ teeth = 8, radius = 1, spinSpeed = 0 }) {
  const groupRef = useRef(null)

  useFrame((_, delta) => {
    if (groupRef.current) {
      groupRef.current.rotation.z += spinSpeed * delta
    }
  })

  const toothAngles = Array.from({ length: teeth }, (_, i) => (i / teeth) * Math.PI * 2)

  return (
    <group ref={groupRef}>
      {/* Hub */}
      <mesh name="hub">
        <cylinderGeometry args={[radius * 0.5, radius * 0.5, radius * 0.4, 24]} />
        <meshStandardMaterial color="gray" />
      </mesh>
      {/* Teeth */}
      {toothAngles.map((angle, i) => (
        <mesh
          key={i}
          name={`tooth-${i}`}
          position={[Math.cos(angle) * radius, Math.sin(angle) * radius, 0]}
          rotation={[0, 0, angle]}
        >
          <boxGeometry args={[radius * 0.4, radius * 0.25, radius * 0.3]} />
          <meshStandardMaterial color="silver" />
        </mesh>
      ))}
    </group>
  )
}

export default Gear

