import { describe, it, expect } from 'vitest'
import * as React from 'react'
import ReactThreeTestRenderer from '@react-three/test-renderer'
import { Gear } from '../src/Gear.jsx'

const EPS = 1e-6

function getToothMeshes(scene) {
  const teeth = []
  scene.traverse((node) => {
    if (node.isMesh && node.geometry?.type === 'BoxGeometry') {
      teeth.push(node)
    }
  })
  return teeth
}

describe('<Gear /> (headless scene graph)', () => {
  it('renders a hub plus the requested number of teeth at the requested radius', async () => {
    const renderer = await ReactThreeTestRenderer.create(
      <Gear teeth={8} radius={2} spinSpeed={Math.PI} />
    )

    const teeth = getToothMeshes(renderer.scene)
    expect(teeth).toHaveLength(8)

    // Every tooth sits exactly `radius` away from the hub axis (origin, Z axis).
    for (const tooth of teeth) {
      const dist = Math.hypot(tooth.position.x, tooth.position.y, tooth.position.z)
      expect(Math.abs(dist - 2)).toBeLessThanOrEqual(EPS)
    }

    // Hub is present too.
    const hub = renderer.scene.getObjectByName('hub')
    expect(hub?.isMesh).toBe(true)
  })

  it('advances rotation.z by spinSpeed * elapsed time', async () => {
    const renderer = await ReactThreeTestRenderer.create(
      <Gear teeth={8} radius={2} spinSpeed={Math.PI} />
    )

    const gear = renderer.scene.children[0]
    const before = gear.rotation.z

    // 60 frames of 1/60s => 1 second of simulated time => PI radians.
    await renderer.advanceFrames(60, 1 / 60)

    const after = gear.rotation.z
    expect(after - before).toBeCloseTo(Math.PI, { precision: undefined })
    expect(Math.abs(after - before - Math.PI)).toBeLessThanOrEqual(5e-2)
  })

  it('rerenders with a different tooth count', async () => {
    const renderer = await ReactThreeTestRenderer.create(
      <Gear teeth={8} radius={2} spinSpeed={Math.PI} />
    )

    expect(getToothMeshes(renderer.scene)).toHaveLength(8)

    await renderer.update(<Gear teeth={12} radius={2} spinSpeed={Math.PI} />)
    expect(getToothMeshes(renderer.scene)).toHaveLength(12)
  })
})

